// Minimal reproduction: dequeue on empty queue
import { AsyncQueue } from "../src/queue.ts";

console.log("=== Reproduction: dequeue on empty queue ===\n");

const q = new AsyncQueue<string>();

// Test 1: dequeue on empty queue should throw
console.log("Test 1: dequeue() on empty queue");
try {
  q.dequeue();
  console.log("  FAIL: No error thrown (bug present)");
  process.exit(1);
} catch (e: any) {
  if (/empty/i.test(e.message)) {
    console.log("  PASS: Threw Error with message:", JSON.stringify(e.message));
  } else {
    console.log("  FAIL: Threw unexpected error:", e.message);
    process.exit(1);
  }
}

// Test 2: dequeue after enqueue should work normally
console.log("\nTest 2: enqueue then dequeue");
q.enqueue("hello");
const job = q.dequeue();
if (job && job.payload === "hello") {
  console.log("  PASS: Dequeued job with payload:", JSON.stringify(job.payload));
} else {
  console.log("  FAIL: Expected job with payload 'hello', got:", job);
  process.exit(1);
}

// Test 3: size() and isEmpty() still work correctly
console.log("\nTest 3: size() and isEmpty() after dequeue");
q.enqueue("a");
q.enqueue("b");
console.log("  size() after 2 enqueues:", q.size());
console.log("  isEmpty():", q.isEmpty());
